17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.ArrayList;
25	import java.util.Collection;
26	import java.util.List;
27	import java.util.Locale;
28	import java.util.Map;
29	import java.util.UUID;
30	import java.util.regex.Pattern;
31	
32	import org.slf4j.Logger;
33	import org.slf4j.LoggerFactory;
34	import org.springframework.http.HttpHeaders;
35	import org.springframework.http.HttpStatus;
36	import org.springframework.http.ResponseEntity;
37	import org.springframework.samples.petclinic.mapper.IdentityKeyDeriver;
38	import org.springframework.samples.petclinic.mapper.LocalityDeriver;
39	import org.springframework.samples.petclinic.mapper.OwnerMapper;
40	import org.springframework.samples.petclinic.mapper.PetMapper;
41	import org.springframework.samples.petclinic.mapper.VisitMapper;
42	import org.springframework.samples.petclinic.model.Owner;
43	import org.springframework.samples.petclinic.model.Pet;
44	import org.springframework.samples.petclinic.model.Visit;
45	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
46	import org.springframework.samples.petclinic.rest.advice.DailyRegistrationLimitException;
47	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
48	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
49	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
50	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
51	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
52	import org.springframework.samples.petclinic.rest.api.OwnersApi;
53	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
54	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
55	import org.springframework.samples.petclinic.rest.dto.PetDto;
56	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
57	import org.springframework.samples.petclinic.rest.dto.VisitDto;
58	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
59	import org.springframework.samples.petclinic.service.ClinicService;
60	import org.springframework.security.access.prepost.PreAuthorize;
61	import org.springframework.web.bind.annotation.CrossOrigin;
62	import org.springframework.web.bind.annotation.RequestMapping;
63	import org.springframework.web.bind.annotation.RestController;
64	import org.springframework.web.util.UriComponentsBuilder;
65	
66	import jakarta.transaction.Transactional;
67	
68	/**
69	 * @author Vitaliy Fedoriv
70	 */
71	
72	@RestController
73	@CrossOrigin(exposedHeaders = "errors, content-type")
74	@RequestMapping("/api")
75	public class OwnerRestControllerV1 implements OwnersApi {
76	
77	    /**
78	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
79	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
80	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
81	     */
82	    private static final Pattern EMAIL_PATTERN =
83	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
84	
85	    /** Dedicated audit logger; carries owner lifecycle side-effects. */
86	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
87	
88	    private final ClinicService clinicService;
89	
90	    private final OwnerMapper ownerMapper;
91	
92	    private final PetMapper petMapper;
93	
94	    private final VisitMapper visitMapper;
95	
96	    public OwnerRestControllerV1(ClinicService clinicService,
97	                                 OwnerMapper ownerMapper,
98	                                 PetMapper petMapper,
99	                                 VisitMapper visitMapper) {
100	        this.clinicService = clinicService;
101	        this.ownerMapper = ownerMapper;
102	        this.petMapper = petMapper;
103	        this.visitMapper = visitMapper;
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
109	        Collection<Owner> owners;
110	        if (lastName != null) {
111	            owners = this.clinicService.findOwnerByLastName(lastName);
112	        } else {
113	            owners = this.clinicService.findAllOwners();
114	        }
115	        if (owners.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
124	        Owner owner = this.clinicService.findOwnerById(ownerId);
125	        if (owner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        List<String> missingFields = new ArrayList<>();
135	        if (isBlank(ownerFieldsDto.getFirstName())) {
136	            missingFields.add("firstName");
137	        }
138	        if (isBlank(ownerFieldsDto.getLastName())) {
139	            missingFields.add("lastName");
140	        }
141	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
142	        if (isBlank(normalizedAddress)) {
143	            missingFields.add("address");
144	        }
145	        if (isBlank(ownerFieldsDto.getCity())) {
146	            missingFields.add("city");
147	        }
148	        if (isBlank(ownerFieldsDto.getTelephone())) {
149	            missingFields.add("telephone");
150	        }
151	        if (!missingFields.isEmpty()) {
152	            throw new MissingOwnerFieldsException(missingFields);
153	        }
154	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
155	        LocalDate registrationDate = toBusinessDay(
156	            ownerFieldsDto.getRegistrationDate() != null
157	                ? ownerFieldsDto.getRegistrationDate()
158	                : LocalDate.now());
159	        long registeredOnDay = this.clinicService.findAllOwners().stream()
160	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
161	            .count();
162	        if (registeredOnDay >= 100) {
163	            throw new DailyRegistrationLimitException(
164	                "100 or more owners have already been registered today");
165	        }
166	        boolean bulkSignupWarning = registeredOnDay > 80;
167	        String city = ownerFieldsDto.getCity();
168	        long ownersInCity = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
170	            .count();
171	        if (ownersInCity >= 50) {
172	            throw new CityAtCapacityException(
173	                "the owner's city already contains 50 or more owners");
174	        }
175	        ownerFieldsDto.setAddress(normalizedAddress);
176	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
177	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
178	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
179	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
180	            .toList();
181	        String householdId = null;
182	        if (!householdMembers.isEmpty()) {
183	            // Owners sharing a normalized last name and address form a household with a
184	            // stable shared identifier; backfill any members created before it was formed.
185	            // The household id is part of the identity key, so two members with different
186	            // telephones have different identity keys and are both allowed.
187	            householdId = householdId(lastName, normalizedAddress);
188	            for (Owner member : householdMembers) {
189	                if (!householdId.equals(member.getHouseholdId())) {
190	                    member.setHouseholdId(householdId);
191	                    this.clinicService.saveOwner(member);
192	                }
193	            }
194	        }
195	        String telephone = toE164(ownerFieldsDto.getTelephone());
196	        ownerFieldsDto.setTelephone(telephone);
197	        String email = normalizeEmail(ownerFieldsDto.getEmail());
198	        ownerFieldsDto.setEmail(email);
199	        // Single, consolidated duplicate check: reject only when the new owner's whole
200	        // derived identity key (telephone|email|householdId) equals an existing owner's.
201	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
202	        boolean identityInUse = this.clinicService.findAllOwners().stream()
203	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
204	                existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
205	        if (identityInUse) {
206	            throw new DuplicateIdentityException(
207	                "an owner with the same identity key already exists");
208	        }
209	        HttpHeaders headers = new HttpHeaders();
210	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
211	        owner.setRegistrationDate(registrationDate);
212	        owner.setCustomerCode(
213	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
214	        owner.setHouseholdId(householdId);
215	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
216	        owner.setBulkSignupWarning(bulkSignupWarning);
217	        // Household size after this create: existing members plus the owner being created.
218	        owner.setHouseholdSize(householdMembers.size() + 1);
219	        this.clinicService.saveOwner(owner);
220	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
221	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
222	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
223	            ownerDto.getMembershipLevel());
224	        headers.setLocation(UriComponentsBuilder.newInstance()
225	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
226	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
232	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
233	        if (currentOwner == null) {
234	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	        }
236	        currentOwner.setAddress(ownerFieldsDto.getAddress());
237	        currentOwner.setCity(ownerFieldsDto.getCity());
238	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
239	        currentOwner.setLastName(ownerFieldsDto.getLastName());
240	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
241	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
242	        this.clinicService.saveOwner(currentOwner);
243	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
244	    }
245	
246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Transactional
248	    @Override
249	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
250	        Owner owner = this.clinicService.findOwnerById(ownerId);
251	        if (owner == null) {
252	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
253	        }
254	        this.clinicService.deleteOwner(owner);
255	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
256	    }
257	
258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
261	        Owner owner = this.clinicService.findOwnerById(ownerId);
262	        if (owner == null) {
263	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
264	        }
265	        HttpHeaders headers = new HttpHeaders();
266	        Pet pet = petMapper.toPet(petFieldsDto);
267	        owner.setId(ownerId);
268	        pet.setOwner(owner);
269	        pet.getType().setName(null);
270	        this.clinicService.savePet(pet);
271	        PetDto petDto = petMapper.toPetDto(pet);
272	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
273	            .buildAndExpand(pet.getId()).toUri());
274	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
275	    }
276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Override
279	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
280	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
281	        if (currentOwner != null) {
282	            Pet currentPet = this.clinicService.findPetById(petId);
283	            if (currentPet != null) {
284	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
285	                currentPet.setName(petFieldsDto.getName());
286	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
287	                this.clinicService.savePet(currentPet);
288	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
289	            }
290	        }
291	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
292	    }
293	
294	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
295	    @Override
296	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
297	        HttpHeaders headers = new HttpHeaders();
298	        Visit visit = visitMapper.toVisit(visitFieldsDto);
299	        Pet pet = new Pet();
300	        pet.setId(petId);
301	        visit.setPet(pet);
302	        this.clinicService.saveVisit(visit);
303	        VisitDto visitDto = visitMapper.toVisitDto(visit);
304	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
305	            .buildAndExpand(visit.getId()).toUri());
306	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
307	    }
308	
309	
310	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
311	    @Override
312	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
313	        Owner owner = this.clinicService.findOwnerById(ownerId);
314	        if (owner != null) {
315	            Pet pet = owner.getPet(petId);
316	            if (pet != null) {
317	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
318	            }
319	        }
320	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
321	    }
322	
323	    private static boolean isBlank(String value) {
324	        return value == null || value.isBlank();
325	    }
326	
327	    /**
328	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
329	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
330	     * to the effective registration date (whether supplied in the request or defaulted to the server
331	     * date), so every value derived from the registration date sees the adjusted business day.
332	     */
333	    private static LocalDate toBusinessDay(LocalDate date) {
334	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
335	            date = date.plusDays(1);
336	        }
337	        return date;
338	    }
339	
340	    /**
341	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
342	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
343	     * lower-cased so that last names are compared case-insensitively.
344	     */
345	    private static String normalizeHousehold(String value) {
346	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
347	    }
348	
349	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
350	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
351	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
352	
353	    /**
354	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
355	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
356	     * upper-cased, and common street-type abbreviations are expanded token-by-token
357	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
358	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
359	     * used for every address comparison (household-duplicate detection and the shared household id).
360	     */
361	    private static String normalizeAddress(String value) {
362	        if (value == null) {
363	            return "";
364	        }
365	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
366	        if (collapsed.isEmpty()) {
367	            return "";
368	        }
369	        String[] tokens = collapsed.split(" ");
370	        StringBuilder sb = new StringBuilder();
371	        for (int i = 0; i < tokens.length; i++) {
372	            if (i > 0) {
373	                sb.append(' ');
374	            }
375	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
376	        }
377	        return sb.toString();
378	    }
379	
380	    /**
381	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
382	     * deterministic function of the normalized last name and address, so every owner that
383	     * shares those values maps to the same identifier regardless of creation order.
384	     */
385	    private static String householdId(String normalizedLastName, String normalizedAddress) {
386	        String key = normalizedLastName + "\n" + normalizedAddress;
387	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
388	    }
389	
390	    /**
391	     * Builds the {@code customerCode} assigned to a new owner, formatted
392	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
393	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
394	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
395	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
396	     * pure function of the owner's own identity fields.
397	     */
398	    private static String customerCode(String postcode, String telephone, String lastName) {
399	        String region = LocalityDeriver.region(postcode);
400	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
401	            + (lastName == null ? "" : lastName));
402	        return region + "-" + hash8;
403	    }
404	
405	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
406	    private static String sha256Hex8(String s) {
407	        try {
408	            byte[] digest = MessageDigest.getInstance("SHA-256")
409	                .digest(s.getBytes(StandardCharsets.UTF_8));
410	            StringBuilder sb = new StringBuilder(8);
411	            for (int i = 0; i < 4; i++) {
412	                sb.append(String.format("%02X", digest[i]));
413	            }
414	            return sb.toString();
415	        }
416	        catch (NoSuchAlgorithmException e) {
417	            throw new IllegalStateException("SHA-256 not available", e);
418	        }
419	    }
420	
421	    /**
422	     * Counts the existing owners that share the given first name and last name, compared
423	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
424	     * owner currently being created is saved), so it reflects how many namesakes preceded the
425	     * new owner.
426	     */
427	    private int countNamesakes(String firstName, String lastName) {
428	        return (int) this.clinicService.findAllOwners().stream()
429	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
430	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
431	            .count();
432	    }
433	
434	    /**
435	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
436	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
437	     * national one, a single leading {@code '0'} is dropped, and the default country code
438	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
439	     * national number must have the length required by its country code ({@code '+61'} requires 9
440	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
441	     * raised (reported to the client as 400).
442	     */
443	    private static String toE164(String telephone) {
444	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
445	        String digits;
446	        if (cleaned.startsWith("+")) {
447	            digits = cleaned.substring(1);
448	        } else {
449	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
450	            digits = "61" + national;
451	        }
452	        if (!digits.matches("[0-9]{8,15}")) {
453	            throw new InvalidTelephoneException(
454	                "telephone must form a valid E.164 number with 8 to 15 digits");
455	        }
456	        validateNationalLength(digits);
457	        return "+" + digits;
458	    }
459	
460	    /** National-number length required for each supported country code (digits after the code). */
461	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
462	        "61", 9, "1", 10);
463	
464	    /**
465	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
466	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
467	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
468	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
469	     */
470	    private static void validateNationalLength(String digits) {
471	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
472	            String code = entry.getKey();
473	            if (digits.startsWith(code)) {
474	                int nationalLength = digits.length() - code.length();
475	                if (nationalLength != entry.getValue()) {
476	                    throw new InvalidTelephoneException(
477	                        "telephone national number must have " + entry.getValue()
478	                            + " digits for country code +" + code);
479	                }
480	                return;
481	            }
482	        }
483	    }
484	
485	    /**
486	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
487	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
488	     * any 4-digit postcode.
489	     */
490	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
491	        "NSW", new int[] {2000, 2099},
492	        "VIC", new int[] {3000, 3099},
493	        "QLD", new int[] {4000, 4099});
494	
495	    /**
496	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
497	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
498	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
499	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
500	     * no known region accepts any 4-digit postcode. A violation raises an
501	     * {@link InvalidPostcodeException} (reported to the client as 400).
502	     */
503	    private static void validatePostcode(String city, String postcode) {
504	        if (isBlank(postcode)) {
505	            return;
506	        }
507	        if (!postcode.matches("[0-9]{4}")) {
508	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
509	        }
510	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
511	        if (range == null) {
512	            return;
513	        }
514	        int value = Integer.parseInt(postcode);
515	        if (value < range[0] || value > range[1]) {
516	            throw new InvalidPostcodeException(
517	                "postcode is out of range for the owner's city region");
518	        }
519	    }
520	
521	    /**
522	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
523	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
524	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
525	     * stored and returned in canonical form.
526	     */
527	    private static String normalizeEmail(String email) {
528	        if (isBlank(email)) {
529	            return null;
530	        }
531	        String trimmed = email.trim();
532	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
533	            throw new InvalidEmailException("email must be a syntactically valid address");
534	        }
535	        return trimmed.toLowerCase(Locale.ROOT);
536	    }
537	}
